solution.solution.js:
function describeType(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

function copyWith(obj, key, value) {
  return { ...obj, [key]: value };
}

unitTests:
test("types", () => {
  checkEq(describeType(42), "number");
  checkEq(describeType("42"), "string");
  checkEq(describeType(true), "boolean");
  checkEq(describeType(undefined), "undefined");
  checkEq(describeType(10n), "bigint");
  checkEq(describeType(() => 1), "function");
  checkEq(describeType({}), "object");
});

test("the two oddities", () => {
  checkEq(describeType(null), "null");
  checkEq(describeType([1, 2]), "array");
});

test("copies, not changes", () => {
  const original = { name: "Ada", age: 36 };
  const changed = copyWith(original, "age", 37);
  checkEq(changed, { name: "Ada", age: 37 });
  checkEq(original, { name: "Ada", age: 36 });
  check(changed !== original, "copyWith must return a new object");
  checkEq(copyWith({}, "x", 1), { x: 1 });
});

